            //
            aOrbiterC = (((aWandererE + RotL64(aCross, 20U)) + 0xFE17DAE8C9276D46ULL) + aOASaltE[((aIndex + 329U)) & S_SALT1]) + aNonceWordB;
            aOrbiterK = (((aWandererJ + RotL64(aScatter, 13U)) + 0xEFBA6ABE2D91B992ULL) + aOASaltH[(((511U - aIndex) + 341U)) & S_SALT1]) + aNonceWordH;
            aOrbiterH = ((aWandererK + RotL64(aIngress, 29U)) + RotL64(aCarry, 3U)) + 0x7EBED5433F673BE5ULL;
