            //
            aOrbiterK = (aOrbiterK + aOrbiterC) + 0xADC68C27B2427AFEULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterK) ^ 0xE87C5EC1B368BF0FULL) ^ aOUSaltE[(((511U - aIndex) + 185U)) & S_SALT1];
